(** Fixed SM2 base-point precomputation tables and their mathematical model. *)
Require Import Coq.ZArith.ZArith.
Require Import Coq.Bool.Bool.
Require Import Coq.Lists.List.
Require Import Coq.micromega.Lia.
From SimpleC.SL Require Import Mem SeparationLogic.
Require Import Logic.LogicGenerator.demo932.Interface.
From SimpleC.EE.Applications_human.sm2.lib
  Require Import ecc ec_math_refinement.

Import ListNotations.
Import Snaive_C_Rules.
Local Open Scope Z_scope.

(** The C object has type [AFPoint [4][8][256]].  We retain the two
    outer dimensions as 32 windows and flatten only at the memory boundary. *)
Definition SM2_TABLE_WINDOWS : nat := 32%nat.
Definition SM2_TABLE_WINDOW_SIZE : nat := 256%nat.
Definition SM2_TABLE_RECORDS : Z := 8192.

Definition sm2_table_window
    (table : list (list RecordAFPoint)) (window : nat) : list RecordAFPoint :=
  nth window table nil.

Definition sm2_table_record
    (table : list (list RecordAFPoint)) (window byte : nat) : RecordAFPoint :=
  nth byte (sm2_table_window table window) zero_record_afpoint.

Definition sm2_table_flatten
    (table : list (list RecordAFPoint)) : list RecordAFPoint :=
  List.concat table.

Definition sm2_record_x (record : RecordAFPoint) : Z :=
  u64_list_value record.(AFPoint_x).(u32_v).

Definition sm2_record_y (record : RecordAFPoint) : Z :=
  u64_list_value record.(AFPoint_y).(u32_v).

Definition sm2_base_table_point (window byte : nat) : ec_point :=
  sm2_point_mul
    (Z.of_nat byte * 256 ^ Z.of_nat window)
    SM2_G_POINT.

Definition SM2_G_RECORD : RecordAFPoint :=
  make_record_afpoint
    (make_record_u32 SM2_G_X_LIMBS)
    (make_record_u32 SM2_G_Y_LIMBS).

(** A compact executable certificate checker.  Its slope certificates are
    generated from the fixed literals, and the checked coordinate equations
    are connected to functional point addition by refinement lemmas.  This
    module is an implementation detail; consumer specifications use the
    mathematical operations below. *)
Module TableCertificateChecker.

Definition coordinate_check (x : Z) : bool :=
  (0 <=? x) && (x <? SM2_P_Z).

Definition affine_on_curve_check (x y : Z) : bool :=
  andb (coordinate_check x)
    (andb (coordinate_check y)
      ((y * y) mod SM2_P_Z =?
       (x * x * x + SM2_A_Z * x + SM2_B_Z) mod SM2_P_Z)).

Definition slope_check
    (numerator denominator slope : Z) : bool :=
  andb (coordinate_check slope)
    (((denominator * slope - numerator) mod SM2_P_Z) =? 0).

Definition affine_sum_check
    (x1 y1 x2 slope x3 y3 : Z) : bool :=
  andb (x3 =? (slope * slope - x1 - x2) mod SM2_P_Z)
    (y3 =? (slope * (x1 - x3) - y1) mod SM2_P_Z).

Definition affine_add_equations_check
    (left right result : RecordAFPoint) (slope : Z) : bool :=
  let x1 := sm2_record_x left in
  let y1 := sm2_record_y left in
  let x2 := sm2_record_x right in
  let y2 := sm2_record_y right in
  let x3 := sm2_record_x result in
  let y3 := sm2_record_y result in
  if x1 =? x2 then
    andb (y1 =? y2)
      (andb (negb (((2 * y1) mod SM2_P_Z) =? 0))
        (andb
          (slope_check (3 * x1 * x1 + SM2_A_Z) (2 * y1) slope)
          (affine_sum_check x1 y1 x2 slope x3 y3)))
  else
    andb (slope_check (y2 - y1) (x2 - x1) slope)
      (affine_sum_check x1 y1 x2 slope x3 y3).

Definition affine_add_check
    (left right result : RecordAFPoint) (slope : Z) : bool :=
  andb (affine_on_curve_check (sm2_record_x left) (sm2_record_y left))
    (andb
      (affine_on_curve_check (sm2_record_x right) (sm2_record_y right))
      (andb
        (affine_on_curve_check (sm2_record_x result) (sm2_record_y result))
        (affine_add_equations_check left right result slope))).

Lemma coordinate_check_sound :
  forall x,
    coordinate_check x = true ->
    0 <= x < SM2_P_Z.
Proof.
  intros x H.
  unfold coordinate_check in H.
  apply andb_true_iff in H as [Hlo Hhi].
  apply Z.leb_le in Hlo.
  apply Z.ltb_lt in Hhi.
  lia.
Qed.

Lemma affine_on_curve_check_sound :
  forall x y,
    affine_on_curve_check x y = true ->
    sm2_affine_on_curve x y.
Proof.
  intros x y H.
  unfold affine_on_curve_check in H.
  apply andb_true_iff in H as [Hx H].
  apply andb_true_iff in H as [Hy Heq].
  apply Z.eqb_eq in Heq.
  unfold sm2_affine_on_curve.
  split; [exact (coordinate_check_sound x Hx) |].
  split; [exact (coordinate_check_sound y Hy) |].
  apply (proj2 (sm2_affine_equation_iff x y)).
  exact Heq.
Qed.

Lemma slope_check_sound :
  forall numerator denominator slope,
    slope_check numerator denominator slope = true ->
    sm2_affine_slope numerator denominator slope.
Proof.
  intros numerator denominator slope H.
  unfold slope_check in H.
  apply andb_true_iff in H as [Hrange Heq].
  apply Z.eqb_eq in Heq.
  unfold sm2_affine_slope.
  split.
  - exact (coordinate_check_sound slope Hrange).
  - exact Heq.
Qed.

Lemma affine_sum_check_sound :
  forall x1 y1 x2 slope x3 y3,
    affine_sum_check x1 y1 x2 slope x3 y3 = true ->
    sm2_affine_sum x1 y1 x2 slope x3 y3.
Proof.
  intros x1 y1 x2 slope x3 y3 H.
  unfold affine_sum_check in H.
  apply andb_true_iff in H as [Hx Hy].
  apply Z.eqb_eq in Hx.
  apply Z.eqb_eq in Hy.
  unfold sm2_affine_sum.
  auto.
Qed.

Lemma affine_add_check_sound :
  forall left right result slope,
    affine_add_check left right result slope = true ->
    exists (Hleft : sm2_affine_on_curve
               (sm2_record_x left) (sm2_record_y left))
           (Hright : sm2_affine_on_curve
               (sm2_record_x right) (sm2_record_y right))
           (Hresult : sm2_affine_on_curve
               (sm2_record_x result) (sm2_record_y result)),
      sm2_point_add
        (ec_point_of_affine
          (sm2_record_x left) (sm2_record_y left) Hleft)
        (ec_point_of_affine
          (sm2_record_x right) (sm2_record_y right) Hright) =
      ec_point_of_affine
        (sm2_record_x result) (sm2_record_y result) Hresult.
Proof.
  intros left right result slope H.
  unfold affine_add_check in H.
  cbn zeta in H.
  apply andb_true_iff in H as [Hleft H].
  apply andb_true_iff in H as [Hright H].
  apply andb_true_iff in H as [Hresult Hbranch].
  unfold affine_add_equations_check in Hbranch.
  cbn zeta in Hbranch.
  pose proof (affine_on_curve_check_sound _ _ Hleft) as HCleft.
  pose proof (affine_on_curve_check_sound _ _ Hright) as HCright.
  pose proof (affine_on_curve_check_sound _ _ Hresult) as HCresult.
  exists HCleft, HCright, HCresult.
  destruct (sm2_record_x left =? sm2_record_x right) eqn:Hx.
  - apply Z.eqb_eq in Hx.
    cbn zeta in Hbranch.
    apply andb_true_iff in Hbranch as [Hy Hbranch].
    apply andb_true_iff in Hbranch as [Hnonzero Hbranch].
    apply andb_true_iff in Hbranch as [Hslope Hsum].
    apply Z.eqb_eq in Hy.
    apply negb_true_iff in Hnonzero.
    apply Z.eqb_neq in Hnonzero.
    assert (Hright_point :
      ec_point_of_affine
        (sm2_record_x right) (sm2_record_y right) HCright =
      ec_point_of_affine
        (sm2_record_x left) (sm2_record_y left) HCleft).
    { unfold ec_point_of_affine.
      apply (SMain.curve_elt_irr sm2_curve_theory).
      - now rewrite Hx.
      - now rewrite Hy. }
    rewrite Hright_point.
    change
      (sm2_point_double
        (ec_point_of_affine
          (sm2_record_x left) (sm2_record_y left) HCleft) =
       ec_point_of_affine
         (sm2_record_x result) (sm2_record_y result) HCresult).
    pose proof (slope_check_sound _ _ _ Hslope)
      as [Hslope_range Hslope_equation].
    pose proof (affine_sum_check_sound _ _ _ _ _ _ Hsum)
      as [Hresult_x Hresult_y].
    apply (sm2_point_double_affine
      (sm2_record_x left) (sm2_record_y left) slope
      (sm2_record_x result) (sm2_record_y result)
      HCleft HCresult).
    + now apply sm2_point_on_curve_y_nonzero with
        (x := sm2_record_x left).
    + apply (proj2 (sm2_eqm_iff_sub_mod_zero _ _)).
      exact Hslope_equation.
    + rewrite <- Hx in Hresult_x.
      replace (slope * slope - 2 * sm2_record_x left) with
        (slope * slope - sm2_record_x left - sm2_record_x left)
        by ring.
      exact Hresult_x.
    + exact Hresult_y.
  - apply Z.eqb_neq in Hx.
    cbn zeta in Hbranch.
    apply andb_true_iff in Hbranch as [Hslope Hsum].
    apply (sm2_point_add_affine_distinct
      (sm2_record_x left) (sm2_record_y left)
      (sm2_record_x right) (sm2_record_y right)
      slope
      (sm2_record_x result) (sm2_record_y result)
      HCleft HCright HCresult).
    + exact Hx.
    + exact (slope_check_sound _ _ _ Hslope).
    + exact (affine_sum_check_sound _ _ _ _ _ _ Hsum).
Qed.

Lemma affine_add_equations_check_sound :
  forall left right result slope,
    affine_on_curve_check (sm2_record_x left) (sm2_record_y left) = true ->
    affine_on_curve_check (sm2_record_x right) (sm2_record_y right) = true ->
    affine_on_curve_check (sm2_record_x result) (sm2_record_y result) = true ->
    affine_add_equations_check left right result slope = true ->
    exists (Hleft_curve : sm2_affine_on_curve
               (sm2_record_x left) (sm2_record_y left))
           (Hright_curve : sm2_affine_on_curve
               (sm2_record_x right) (sm2_record_y right))
           (Hresult_curve : sm2_affine_on_curve
               (sm2_record_x result) (sm2_record_y result)),
      sm2_point_add
        (ec_point_of_affine
          (sm2_record_x left) (sm2_record_y left) Hleft_curve)
        (ec_point_of_affine
          (sm2_record_x right) (sm2_record_y right) Hright_curve) =
      ec_point_of_affine
        (sm2_record_x result) (sm2_record_y result) Hresult_curve.
Proof.
  intros left right result slope Hleft Hright Hresult Hequations.
  apply affine_add_check_sound with (slope := slope).
  unfold affine_add_check.
  now rewrite Hleft, Hright, Hresult, Hequations.
Qed.

End TableCertificateChecker.

(** Consumer-facing mathematical statement.  Every stored record refines
    the expected scalar multiple; the certificate's intermediate addition
    chain remains private to this file. *)
Definition sm2_base_table_correct
    (table : list (list RecordAFPoint)) : Prop :=
  length table = SM2_TABLE_WINDOWS /\
  Forall (fun window => length window = SM2_TABLE_WINDOW_SIZE) table /\
  forall window byte,
    (window < SM2_TABLE_WINDOWS)%nat ->
    (byte < SM2_TABLE_WINDOW_SIZE)%nat ->
    afpoint_represents
      (sm2_record_x (sm2_table_record table window byte))
      (sm2_record_y (sm2_table_record table window byte))
      (sm2_base_table_point window byte).

Definition sm2_windowb
    (table : list (list RecordAFPoint))
    (slopes : list (list Z)) (window : nat) : bool :=
  let zero := sm2_table_record table window 0 in
  let base := sm2_table_record table window 1 in
  andb (sm2_record_x zero =? 0)
    (andb (sm2_record_y zero =? 0)
      (andb
        (forallb
          (fun byte =>
             let record := sm2_table_record table window byte in
             TableCertificateChecker.affine_on_curve_check
               (sm2_record_x record) (sm2_record_y record))
          (seq 1 255))
        (forallb
          (fun byte =>
             TableCertificateChecker.affine_add_equations_check
               (sm2_table_record table window byte)
               base
               (sm2_table_record table window (S byte))
               (nth byte (nth window slopes nil) 0))
          (seq 1 254)))).

Definition sm2_window_linkb
    (table : list (list RecordAFPoint))
    (link_slopes : list Z) (window : nat) : bool :=
  TableCertificateChecker.affine_add_check
    (sm2_table_record table window 128)
    (sm2_table_record table window 128)
    (sm2_table_record table (S window) 1)
    (nth window link_slopes 0).

Definition sm2_base_table_check
    (table : list (list RecordAFPoint))
    (slopes : list (list Z)) (link_slopes : list Z) : bool :=
  andb (Nat.eqb (length table) SM2_TABLE_WINDOWS)
    (andb
      (forallb
        (fun window => Nat.eqb (length window) SM2_TABLE_WINDOW_SIZE)
        table)
      (andb
        (andb
          (sm2_record_x (sm2_table_record table 0 1) =?
           sm2_record_x SM2_G_RECORD)
          (sm2_record_y (sm2_table_record table 0 1) =?
           sm2_record_y SM2_G_RECORD))
        (andb
          (forallb (sm2_windowb table slopes) (seq 0 SM2_TABLE_WINDOWS))
          (forallb
            (sm2_window_linkb table link_slopes) (seq 0 31))))).

Lemma sm2_checked_add_represents :
  forall left right result slope Pleft Pright,
    TableCertificateChecker.affine_on_curve_check
      (sm2_record_x left) (sm2_record_y left) = true ->
    TableCertificateChecker.affine_on_curve_check
      (sm2_record_x right) (sm2_record_y right) = true ->
    TableCertificateChecker.affine_on_curve_check
      (sm2_record_x result) (sm2_record_y result) = true ->
    TableCertificateChecker.affine_add_equations_check
      left right result slope = true ->
    afpoint_represents (sm2_record_x left) (sm2_record_y left) Pleft ->
    afpoint_represents (sm2_record_x right) (sm2_record_y right) Pright ->
    afpoint_represents
      (sm2_record_x result) (sm2_record_y result)
      (sm2_point_add Pleft Pright).
Proof.
  intros left right result slope Pleft Pright
    Hleft Hright Hresult Hadd Hleft_rep Hright_rep.
  destruct (TableCertificateChecker.affine_add_equations_check_sound
      left right result slope Hleft Hright Hresult Hadd)
    as [HCleft [HCright [HCresult Hpoint_add]]].
  pose proof (afpoint_represents_on_curve_complete
    _ _ Pleft HCleft Hleft_rep) as HPleft.
  pose proof (afpoint_represents_on_curve_complete
    _ _ Pright HCright Hright_rep) as HPright.
  rewrite HPleft, HPright, Hpoint_add.
  change (ec_point_affine_coordinates
    (ec_point_of_affine
      (sm2_record_x result) (sm2_record_y result) HCresult)
    (sm2_record_x result) (sm2_record_y result)).
  apply ec_point_of_affine_coordinates.
Qed.

Lemma sm2_checked_double_represents :
  forall left result slope point,
    TableCertificateChecker.affine_add_check
      left left result slope = true ->
    afpoint_represents (sm2_record_x left) (sm2_record_y left) point ->
    afpoint_represents
      (sm2_record_x result) (sm2_record_y result)
      (sm2_point_double point).
Proof.
  intros left result slope point Hcheck Hrep.
  destruct (TableCertificateChecker.affine_add_check_sound
      left left result slope Hcheck)
    as [HCleft1 [HCleft2 [HCresult Hadd]]].
  pose proof (afpoint_represents_on_curve_complete
    _ _ point HCleft1 Hrep) as Hpoint1.
  pose proof (afpoint_represents_on_curve_complete
    _ _ point HCleft2 Hrep) as Hpoint2.
  unfold sm2_point_double.
  rewrite Hpoint1 at 1.
  rewrite Hpoint2 at 1.
  rewrite Hadd.
  change (ec_point_affine_coordinates
    (ec_point_of_affine
      (sm2_record_x result) (sm2_record_y result) HCresult)
    (sm2_record_x result) (sm2_record_y result)).
  apply ec_point_of_affine_coordinates.
Qed.

Lemma sm2_window_check_sound_from_base :
  forall table slopes window base,
    sm2_windowb table slopes window = true ->
    afpoint_represents
      (sm2_record_x (sm2_table_record table window 1))
      (sm2_record_y (sm2_table_record table window 1)) base ->
    forall byte,
      (byte < SM2_TABLE_WINDOW_SIZE)%nat ->
      afpoint_represents
        (sm2_record_x (sm2_table_record table window byte))
        (sm2_record_y (sm2_table_record table window byte))
        (sm2_point_mul (Z.of_nat byte) base).
Proof.
  intros table slopes window base Hwindow Hbase.
  unfold sm2_windowb in Hwindow.
  cbn zeta in Hwindow.
  apply andb_true_iff in Hwindow as [Hzero_x Hwindow].
  apply andb_true_iff in Hwindow as [Hzero_y Hwindow].
  apply andb_true_iff in Hwindow as [Hcurves Hsteps].
  apply Z.eqb_eq in Hzero_x.
  apply Z.eqb_eq in Hzero_y.
  intros byte.
  induction byte as [|previous IH]; intros Hbyte.
  - rewrite sm2_point_mul_zero.
    cbn [afpoint_represents afpoint_infinity].
    split; assumption.
  - destruct previous as [|previous].
    + rewrite sm2_point_mul_one.
      exact Hbase.
    + assert (Hprevious : (S previous < SM2_TABLE_WINDOW_SIZE)%nat)
        by lia.
      specialize (IH Hprevious).
      assert (Hin_step : In (S previous) (seq 1 254)).
      { apply in_seq.
        unfold SM2_TABLE_WINDOW_SIZE in Hbyte.
        lia. }
      apply forallb_forall with (x := S previous) in Hsteps;
        [|exact Hin_step].
      assert (Hleft :
        TableCertificateChecker.affine_on_curve_check
          (sm2_record_x
            (sm2_table_record table window (S previous)))
          (sm2_record_y
            (sm2_table_record table window (S previous))) = true).
      { apply forallb_forall with (x := S previous) in Hcurves.
        - exact Hcurves.
        - apply in_seq.
          unfold SM2_TABLE_WINDOW_SIZE in Hbyte.
          lia. }
      assert (Hbase_curve :
        TableCertificateChecker.affine_on_curve_check
          (sm2_record_x (sm2_table_record table window 1))
          (sm2_record_y (sm2_table_record table window 1)) = true).
      { apply forallb_forall with (x := 1%nat) in Hcurves.
        - exact Hcurves.
        - apply in_seq. lia. }
      assert (Hresult :
        TableCertificateChecker.affine_on_curve_check
          (sm2_record_x
            (sm2_table_record table window (S (S previous))))
          (sm2_record_y
            (sm2_table_record table window (S (S previous)))) = true).
      { apply forallb_forall with (x := S (S previous)) in Hcurves.
        - exact Hcurves.
        - apply in_seq.
          unfold SM2_TABLE_WINDOW_SIZE in Hbyte.
          lia. }
      pose proof (sm2_checked_add_represents
        (sm2_table_record table window (S previous))
        (sm2_table_record table window 1)
        (sm2_table_record table window (S (S previous)))
        (nth (S previous) (nth window slopes nil) 0)
        (sm2_point_mul (Z.of_nat (S previous)) base) base
        Hleft Hbase_curve Hresult Hsteps IH Hbase) as Hadd.
      replace (Z.of_nat (S (S previous))) with
        (Z.of_nat (S previous) + 1) by lia.
      rewrite sm2_point_mul_add by lia.
      rewrite sm2_point_mul_one.
      exact Hadd.
Qed.

Lemma sm2_base_table_check_sound :
  forall table slopes link_slopes,
    sm2_base_table_check table slopes link_slopes = true ->
    sm2_base_table_correct table.
Proof.
  intros table slopes link_slopes Hcheck.
  unfold sm2_base_table_check in Hcheck.
  apply andb_true_iff in Hcheck as [Hlength Hcheck].
  apply andb_true_iff in Hcheck as [Hlengths Hcheck].
  apply andb_true_iff in Hcheck as [Hgenerator Hcheck].
  apply andb_true_iff in Hgenerator as [Hgenerator_x Hgenerator_y].
  apply andb_true_iff in Hcheck as [Hwindows Hlinks].
  apply Nat.eqb_eq in Hlength.
  apply Z.eqb_eq in Hgenerator_x.
  apply Z.eqb_eq in Hgenerator_y.
  split; [exact Hlength |].
  split.
  - apply Forall_forall.
    intros window Hin.
    apply forallb_forall with (x := window) in Hlengths; [|exact Hin].
    now apply Nat.eqb_eq in Hlengths.
  - assert (Hbase : forall window,
        (window < SM2_TABLE_WINDOWS)%nat ->
        afpoint_represents
          (sm2_record_x (sm2_table_record table window 1))
          (sm2_record_y (sm2_table_record table window 1))
          (sm2_point_mul (256 ^ Z.of_nat window) SM2_G_POINT)).
    { intros window.
      induction window as [|previous IH]; intros Hwindow.
      - rewrite Z.pow_0_r, sm2_point_mul_one.
        rewrite Hgenerator_x, Hgenerator_y.
        change
          (afpoint_represents
            (sm2_record_x SM2_G_RECORD)
            (sm2_record_y SM2_G_RECORD) SM2_G_POINT).
        vm_compute.
        split; reflexivity.
      - assert (Hprevious_window :
          (previous < SM2_TABLE_WINDOWS)%nat) by lia.
        specialize (IH Hprevious_window).
        assert (Hin_window : In previous (seq 0 SM2_TABLE_WINDOWS)).
        { apply in_seq. lia. }
        pose proof Hwindows as Hwindow_check.
        apply forallb_forall with (x := previous) in Hwindow_check;
          [|exact Hin_window].
        pose proof (sm2_window_check_sound_from_base
          table slopes previous
          (sm2_point_mul (256 ^ Z.of_nat previous) SM2_G_POINT)
          Hwindow_check IH 128
          ltac:(unfold SM2_TABLE_WINDOW_SIZE; lia)) as Hrecord128.
        assert (Hin_link : In previous (seq 0 31)).
        { apply in_seq.
          unfold SM2_TABLE_WINDOWS in Hwindow.
          lia. }
        pose proof Hlinks as Hlink.
        apply forallb_forall with (x := previous) in Hlink;
          [|exact Hin_link].
        unfold sm2_window_linkb in Hlink.
        pose proof (sm2_checked_double_represents
          (sm2_table_record table previous 128)
          (sm2_table_record table (S previous) 1)
          (nth previous link_slopes 0)
          (sm2_point_mul 128
            (sm2_point_mul
              (256 ^ Z.of_nat previous) SM2_G_POINT))
          Hlink Hrecord128) as Hnext.
        replace (256 ^ Z.of_nat (S previous)) with
          ((256 ^ Z.of_nat previous * 128) * 2).
        2: { rewrite Nat2Z.inj_succ, Z.pow_succ_r by lia. ring. }
        rewrite sm2_point_mul_mul by lia.
        rewrite sm2_point_mul_mul by lia.
        rewrite sm2_point_mul_two.
        exact Hnext. }
    intros window byte Hwindow Hbyte.
    assert (Hin_window : In window (seq 0 SM2_TABLE_WINDOWS)).
    { apply in_seq. lia. }
    pose proof Hwindows as Hwindow_check.
    apply forallb_forall with (x := window) in Hwindow_check;
      [|exact Hin_window].
    pose proof (sm2_window_check_sound_from_base
      table slopes window
      (sm2_point_mul (256 ^ Z.of_nat window) SM2_G_POINT)
      Hwindow_check (Hbase window Hwindow) byte Hbyte) as Hentry.
    unfold sm2_base_table_point.
    replace (Z.of_nat byte * 256 ^ Z.of_nat window) with
      (256 ^ Z.of_nat window * Z.of_nat byte) by ring.
    rewrite sm2_point_mul_mul by lia.
    exact Hentry.
Qed.

(** The Montgomery table stores the same coordinates multiplied by R. *)
Definition sm2_mont_table_correct
    (ordinary montgomery : list (list RecordAFPoint)) : Prop :=
  length montgomery = SM2_TABLE_WINDOWS /\
  Forall (fun window => length window = SM2_TABLE_WINDOW_SIZE) montgomery /\
  forall window byte,
    (window < SM2_TABLE_WINDOWS)%nat ->
    (byte < SM2_TABLE_WINDOW_SIZE)%nat ->
    sm2_record_x (sm2_table_record montgomery window byte) =
      mont_p (sm2_record_x (sm2_table_record ordinary window byte)) /\
    sm2_record_y (sm2_table_record montgomery window byte) =
      mont_p (sm2_record_y (sm2_table_record ordinary window byte)).

Definition sm2_mont_recordb
    (ordinary montgomery : RecordAFPoint) : bool :=
  andb
    (sm2_record_x montgomery =? mont_p (sm2_record_x ordinary))
    (sm2_record_y montgomery =? mont_p (sm2_record_y ordinary)).

Definition sm2_mont_windowb
    (ordinary montgomery : list (list RecordAFPoint))
    (window : nat) : bool :=
  forallb
    (fun byte =>
       sm2_mont_recordb
         (sm2_table_record ordinary window byte)
         (sm2_table_record montgomery window byte))
    (seq 0 SM2_TABLE_WINDOW_SIZE).

Definition sm2_mont_table_check
    (ordinary montgomery : list (list RecordAFPoint)) : bool :=
  andb (Nat.eqb (length montgomery) SM2_TABLE_WINDOWS)
    (andb
      (forallb
        (fun window => Nat.eqb (length window) SM2_TABLE_WINDOW_SIZE)
        montgomery)
      (forallb
        (sm2_mont_windowb ordinary montgomery)
        (seq 0 SM2_TABLE_WINDOWS))).

Lemma sm2_mont_table_check_sound :
  forall ordinary montgomery,
    sm2_mont_table_check ordinary montgomery = true ->
    sm2_mont_table_correct ordinary montgomery.
Proof.
  intros ordinary montgomery Hcheck.
  unfold sm2_mont_table_check in Hcheck.
  apply andb_true_iff in Hcheck as [Hlength Hcheck].
  apply andb_true_iff in Hcheck as [Hlengths Hwindows].
  apply Nat.eqb_eq in Hlength.
  unfold sm2_mont_table_correct.
  split; [exact Hlength |].
  split.
  - apply Forall_forall.
    intros window Hin.
    apply forallb_forall with (x := window) in Hlengths; [|exact Hin].
    now apply Nat.eqb_eq in Hlengths.
  - intros window byte Hwindow Hbyte.
    assert (Hin_window : In window (seq 0 SM2_TABLE_WINDOWS)).
    { apply in_seq. lia. }
    apply forallb_forall with (x := window) in Hwindows;
      [|exact Hin_window].
    unfold sm2_mont_windowb in Hwindows.
    assert (Hin_byte : In byte (seq 0 SM2_TABLE_WINDOW_SIZE)).
    { apply in_seq. lia. }
    apply forallb_forall with (x := byte) in Hwindows; [|exact Hin_byte].
    unfold sm2_mont_recordb in Hwindows.
    apply andb_true_iff in Hwindows as [Hx Hy].
    apply Z.eqb_eq in Hx.
    apply Z.eqb_eq in Hy.
    auto.
Qed.

