(* END GENERATED SM2 TABLE DATA. *)

(** The Montgomery table is a closed transformation of the ordinary table.
    The literal C initializer was independently checked entry-for-entry
    against this definition. *)
Definition sm2_u256_limbs (x : Z) : list Z :=
  let q1 := x / U64_MOD in
  let q2 := q1 / U64_MOD in
  let q3 := q2 / U64_MOD in
  [x mod U64_MOD;
   q1 mod U64_MOD;
   q2 mod U64_MOD;
   q3 mod U64_MOD].

Lemma sm2_u256_limbs_value :
  forall x,
    0 <= x < U256_MOD ->
    u64_list_value (sm2_u256_limbs x) = x.
Proof.
  intros x Hx.
  unfold sm2_u256_limbs.
  rewrite u64_list_value_four.
  unfold u256_of_limbs.
  set (q1 := x / U64_MOD).
  set (q2 := q1 / U64_MOD).
  set (q3 := q2 / U64_MOD).
  assert (Hbase : 0 < U64_MOD) by (cbv [U64_MOD]; lia).
  assert (Hradix : U256_MOD = U64_MOD ^ 4).
  { cbv [U256_MOD U64_MOD]. reflexivity. }
  assert (Hq1 : 0 <= q1 < U64_MOD ^ 3).
  { subst q1. split.
    - apply Z.div_pos; lia.
    - apply Z.div_lt_upper_bound; [exact Hbase |].
      rewrite Hradix in Hx. nia. }
  assert (Hq2 : 0 <= q2 < U64_MOD ^ 2).
  { subst q2. split.
    - apply Z.div_pos; lia.
    - apply Z.div_lt_upper_bound; [exact Hbase |]. nia. }
  assert (Hq3 : 0 <= q3 < U64_MOD).
  { subst q3. split.
    - apply Z.div_pos; lia.
    - apply Z.div_lt_upper_bound; [exact Hbase |]. nia. }
  pose proof (Z.div_mod x U64_MOD ltac:(lia)) as E0.
  pose proof (Z.div_mod q1 U64_MOD ltac:(lia)) as E1.
  pose proof (Z.div_mod q2 U64_MOD ltac:(lia)) as E2.
  rewrite (Z.mod_small q3 U64_MOD Hq3).
  nia.
Qed.

Definition sm2_mont_record (record : RecordAFPoint) : RecordAFPoint :=
  make_record_afpoint
    (make_record_u32 (sm2_u256_limbs (mont_p (sm2_record_x record))))
    (make_record_u32 (sm2_u256_limbs (mont_p (sm2_record_y record)))).

Lemma sm2_mont_record_values :
  forall record,
    sm2_record_x (sm2_mont_record record) = mont_p (sm2_record_x record) /\
    sm2_record_y (sm2_mont_record record) = mont_p (sm2_record_y record).
Proof.
  intros record.
  unfold sm2_mont_record, sm2_record_x, sm2_record_y.
  cbn [AFPoint_x AFPoint_y u32_v].
  split.
  - apply sm2_u256_limbs_value.
    pose proof (mont_p_range
      (u64_list_value (u32_v (AFPoint_x record)))) as Hrange.
    pose proof sm2_p_montgomery_bounds as [[_ Hp_u256] _].
    lia.
  - apply sm2_u256_limbs_value.
    pose proof (mont_p_range
      (u64_list_value (u32_v (AFPoint_y record)))) as Hrange.
    pose proof sm2_p_montgomery_bounds as [[_ Hp_u256] _].
    lia.
Qed.

Definition SM2_MONT_BASE_TABLE_DATA : list (list RecordAFPoint) :=
  map (map sm2_mont_record) SM2_BASE_TABLE_DATA.

Lemma sm2_table_record_map :
  forall (transform : RecordAFPoint -> RecordAFPoint) table window byte,
    (window < length table)%nat ->
    (byte < length (nth window table nil))%nat ->
    sm2_table_record (map (map transform) table) window byte =
      transform (sm2_table_record table window byte).
Proof.
  intros transform table window byte Hwindow Hbyte.
  unfold sm2_table_record, sm2_table_window.
  replace (@nil RecordAFPoint) with
    (map transform (@nil RecordAFPoint)) at 1 by reflexivity.
  rewrite map_nth.
  rewrite (nth_indep _ zero_record_afpoint
    (transform zero_record_afpoint)) by
    (rewrite length_map; exact Hbyte).
  rewrite map_nth.
  reflexivity.
Qed.

Lemma sm2_mont_map_table_correct :
  forall ordinary,
    length ordinary = SM2_TABLE_WINDOWS ->
    Forall (fun window => length window = SM2_TABLE_WINDOW_SIZE) ordinary ->
    sm2_mont_table_correct
      ordinary (map (map sm2_mont_record) ordinary).
Proof.
  intros ordinary Hlength Hlengths.
  assert (Hlengths_forall :
    forall window, In window ordinary ->
      length window = SM2_TABLE_WINDOW_SIZE).
  { exact (proj1 (Forall_forall _ _) Hlengths). }
  unfold sm2_mont_table_correct.
  split.
  - now rewrite length_map.
  - split.
    + apply Forall_forall.
      intros mont_window Hin.
      apply in_map_iff in Hin as [window [<- Hin]].
      rewrite length_map.
      now apply Hlengths_forall.
    + intros window byte Hwindow Hbyte.
      assert (Hrow_length :
        length (nth window ordinary nil) = SM2_TABLE_WINDOW_SIZE).
      { apply Hlengths_forall.
        apply nth_In. rewrite Hlength. exact Hwindow. }
      rewrite (sm2_table_record_map sm2_mont_record ordinary window byte).
      * exact (sm2_mont_record_values
          (sm2_table_record ordinary window byte)).
      * rewrite Hlength. exact Hwindow.
      * rewrite Hrow_length. exact Hbyte.
Qed.

Theorem sm2_mont_base_table_data_correct :
  sm2_mont_table_correct
    SM2_BASE_TABLE_DATA SM2_MONT_BASE_TABLE_DATA.
Proof.
  unfold SM2_MONT_BASE_TABLE_DATA.
  destruct sm2_base_table_data_correct as [Hlength [Hlengths _]].
  now apply sm2_mont_map_table_correct.
Qed.

(** The [4][8] indices select one of the 32 byte windows. *)
Definition sm2_table_window_index (limb byte_in_limb : nat) : nat :=
  (limb * 8 + byte_in_limb)%nat.

Definition sm2_table_point_at
    (table : list (list RecordAFPoint))
    (limb byte_in_limb byte_value : nat) : ec_point :=
  sm2_base_table_point
    (sm2_table_window_index limb byte_in_limb) byte_value.

Lemma concat_uniform_length :
  forall {A : Type} (rows : list (list A)) width,
    Forall (fun row => length row = width) rows ->
    length (List.concat rows) = (length rows * width)%nat.
Proof.
  intros A rows width Hrows.
  induction Hrows as [|row rows Hrow Hrows IH].
  - reflexivity.
  - cbn [List.concat length].
    rewrite length_app, Hrow, IH.
    lia.
Qed.

Lemma nth_concat_uniform :
  forall {A : Type} (rows : list (list A)) width row column default,
    Forall (fun entries => length entries = width) rows ->
    (row < length rows)%nat ->
    (column < width)%nat ->
    nth (row * width + column) (List.concat rows) default =
      nth column (nth row rows nil) default.
Proof.
  intros A rows width row column default Hrows Hrow Hcolumn.
  revert rows Hrows Hrow.
  induction row as [|row IH]; intros rows Hrows Hrow.
  - destruct rows as [|entries rows]; [cbn in Hrow; lia |].
    inversion Hrows as [|? ? Hentries Htail]; subst.
    cbn [List.concat nth].
    rewrite app_nth1; [reflexivity | exact Hcolumn].
  - destruct rows as [|entries rows]; [cbn in Hrow; lia |].
    inversion Hrows as [|? ? Hentries Htail]; subst.
    cbn [List.concat nth].
    rewrite app_nth2.
    + replace (S row * length entries + column - length entries)%nat
        with (row * length entries + column)%nat by lia.
      apply IH; [exact Htail | cbn in Hrow; lia].
    + lia.
Qed.

Lemma sm2_base_table_flatten_length :
  Zlength (sm2_table_flatten SM2_BASE_TABLE_DATA) = SM2_TABLE_RECORDS.
Proof.
  destruct sm2_base_table_data_correct as [Hlength [Hrows _]].
  unfold sm2_table_flatten.
  rewrite Zlength_correct.
  rewrite (concat_uniform_length SM2_BASE_TABLE_DATA
    SM2_TABLE_WINDOW_SIZE Hrows).
  unfold SM2_TABLE_WINDOWS, SM2_TABLE_WINDOW_SIZE, SM2_TABLE_RECORDS in *.
  lia.
Qed.

Lemma sm2_mont_base_table_flatten_length :
  Zlength (sm2_table_flatten SM2_MONT_BASE_TABLE_DATA) =
    SM2_TABLE_RECORDS.
Proof.
  destruct sm2_mont_base_table_data_correct as [Hlength [Hrows _]].
  unfold sm2_table_flatten.
  rewrite Zlength_correct.
  rewrite (concat_uniform_length SM2_MONT_BASE_TABLE_DATA
    SM2_TABLE_WINDOW_SIZE Hrows).
  unfold SM2_TABLE_WINDOWS, SM2_TABLE_WINDOW_SIZE, SM2_TABLE_RECORDS in *.
  lia.
Qed.

Require Import Coq.Strings.String.
Local Open Scope string_scope.
Local Open Scope sac.

Definition sm2_base_table_flat_index
    (limb byte_in_limb byte_value : Z) : Z :=
  Z.of_nat
    (((Z.to_nat limb * 8 + Z.to_nat byte_in_limb) * 256 +
      Z.to_nat byte_value)%nat).

Definition sm2_base_table_record_at
    (limb byte_in_limb byte_value : Z) : RecordAFPoint :=
  sm2_table_record SM2_BASE_TABLE_DATA
    (sm2_table_window_index
      (Z.to_nat limb) (Z.to_nat byte_in_limb))
    (Z.to_nat byte_value).

Lemma sm2_base_table_flatten_record_at :
  forall limb byte_in_limb byte_value,
    0 <= limb < 4 ->
    0 <= byte_in_limb < 8 ->
    0 <= byte_value < 256 ->
    Znth (sm2_base_table_flat_index limb byte_in_limb byte_value)
      (sm2_table_flatten SM2_BASE_TABLE_DATA) zero_record_afpoint =
    sm2_base_table_record_at limb byte_in_limb byte_value.
Proof.
  intros limb byte_in_limb byte_value Hlimb Hbyte_in Hbyte.
  assert (Hlimb_nat : (Z.to_nat limb < 4)%nat).
  {
    change (Z.to_nat limb < Z.to_nat 4)%nat.
    apply (proj1 (Z2Nat.inj_lt limb 4 ltac:(lia) ltac:(lia))).
    lia.
  }
  assert (Hbyte_in_nat : (Z.to_nat byte_in_limb < 8)%nat).
  {
    change (Z.to_nat byte_in_limb < Z.to_nat 8)%nat.
    apply
      (proj1
        (Z2Nat.inj_lt byte_in_limb 8 ltac:(lia) ltac:(lia))).
    lia.
  }
  assert (Hbyte_nat : (Z.to_nat byte_value < 256)%nat).
  {
    change (Z.to_nat byte_value < Z.to_nat 256)%nat.
    apply
      (proj1
        (Z2Nat.inj_lt byte_value 256 ltac:(lia) ltac:(lia))).
    lia.
  }
  destruct sm2_base_table_data_correct as [Hlength [Hrows Hcorrect]].
  unfold sm2_base_table_flat_index, sm2_base_table_record_at,
    sm2_table_record, sm2_table_window, sm2_table_window_index,
    sm2_table_flatten, Znth.
  rewrite Nat2Z.id.
  apply nth_concat_uniform.
  - exact Hrows.
  - unfold SM2_TABLE_WINDOWS in Hlength.
    rewrite Hlength.
    lia.
  - unfold SM2_TABLE_WINDOW_SIZE.
    exact Hbyte_nat.
Qed.

(** Fixed global resource for the ordinary precomputation table.  The pure
    fact and the exact spatial data refer to the same closed Rocq constant;
    no existential table is hidden by this predicate. *)
Definition store_sm2_base_point_table : Assertion :=
  “ sm2_base_table_correct SM2_BASE_TABLE_DATA ” &&
  StructAFPointArray.full
    (&("g_AFTable_for_base_point_mul"))
    SM2_TABLE_RECORDS
    (sm2_table_flatten SM2_BASE_TABLE_DATA).

(** Fixed global resource for the Montgomery table.  Its pure fact ties
    every stored coordinate to the already-verified ordinary table. *)
Definition sm2_mont_base_table_correct : Prop :=
  sm2_base_table_correct SM2_BASE_TABLE_DATA /\
  sm2_mont_table_correct
    SM2_BASE_TABLE_DATA SM2_MONT_BASE_TABLE_DATA.

Definition store_sm2_mont_base_point_table : Assertion :=
  “ sm2_mont_base_table_correct ” &&
  StructAFPointArray.full
    (&("g_montg_AFTable_for_base_point_mul"))
    SM2_TABLE_RECORDS
    (sm2_table_flatten SM2_MONT_BASE_TABLE_DATA).

Definition store_sm2_base_point_tables : Assertion :=
  store_sm2_base_point_table ** store_sm2_mont_base_point_table.

Theorem sm2_mont_base_table_correct_proved :
  sm2_mont_base_table_correct.
Proof.
  split.
  - exact sm2_base_table_data_correct.
  - exact sm2_mont_base_table_data_correct.
Qed.
